import torch.autograd.function

class MyInplaceFunction(torch.autograd.function.InplaceFunction):
    @staticmethod
    def forward(ctx, input, inplace=False):
        ctx.save_for_backward(input)
        ctx.inplace = inplace
        if inplace:
            input.add_(1)
            return input
        else:
            return input + 1

    @staticmethod
    def backward(ctx, grad_output):
        input, = ctx.saved_tensors
        return grad_output, None

input_tensor = torch.randn(3, 3, requires_grad=True)
