A_cdouble = torch.randn(3, 3, dtype=torch.cdouble)

ord_values = [None, 'fro', 'nuc', float('inf'), -float('inf'), 0, 1, -1, 2, -2, 3, 1.5]
dim_values = [None, 0, 1, (0, 1)]
keepdim_values = [True, False]
out_tensors = [torch.empty(3, 3), None]
