for A in [A_float, A_double, A_cfloat, A_cdouble]:
    for ord in ord_values:
        for dim in dim_values:
            for keepdim in keepdim_values:
                for out in out_tensors:
                    for dtype in dtype_values:
                        if ord == 'nuc' and dim is not None and len(dim) != 2:
