                        if ord in ['fro', 'nuc'] and dim is None:
                            torch.linalg.norm(A, ord=ord, dim=dim, keepdim=keepdim, out=out, dtype=dtype)
                        elif dim is not None:
                            torch.linalg.norm(A, ord=ord, dim=dim, keepdim=keepdim, out=out, dtype=dtype)
